// CSD_RATIONALE_BEGIN
// This strategy tracks the full generated output in `generated`, whether we are
// currently inside an arithmetic span in `insideConstrainedOut`, and the active
// constrained contents between delimiters in `currentConstrainedOut`.
// Outside constrained mode, it generates freely but biases toward opening a
// span when either the sampled token is "<<" or the model places "<<" close to
// the current argmax. Inside constrained mode, it uses parser-aware generation:
// if the current arithmetic prefix is complete, it closes with ">>"; otherwise
// it prefers a parser-valid argmax token when available and falls back to a
// constrained helper step. This state supports valid generation because the
// constrained prefix always mirrors the suffix of the full output after the
// opening delimiter, and only parser-valid tokens are appended while inside a
// span.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity: In the unconstrained branch, either we stay outside
//   constrained mode (implication vacuous), or we append "<<" and set
//   currentConstrainedOut := [], which is a valid prefix by precondition. In
//   the complete-prefix branch, CloseConstrainedSpan resets to not-inside, so
//   the implication is vacuous. In the constrained-argmax and constrained-
//   fallback branches, AppendConstrainedToken is called only after a
//   parser-valid next token has been established, so validity is preserved.
// suffix: Outside constrained mode, the invariant is vacuous; when we open a
//   span we append "<<" and set currentConstrainedOut := [], and the length-0
//   suffix matches []. CloseConstrainedSpan appends the closing delimiter and
//   resets currentConstrainedOut to [], so the implication remains true.
//   AppendConstrainedToken appends the same token to both generated and the
//   constrained prefix, preserving suffix equality.
// cost: The unconstrained helper branch bumps helpers.cost by 1 and we also do
//   steps := steps + 1. The eager-open raw-logit branch uses GenerateLogits and
//   queries only, then manually bumps helpers.cost by 1 together with steps.
//   CloseConstrainedSpan and ConstrainedStep each bump helpers.cost by 1 and we
//   increment steps once. AppendConstrainedToken and parser queries do not bump
//   helpers.cost, so helpers.cost <= steps is preserved in every branch.
// progress: In the unconstrained helper and eager-open branches we append at
//   most one token to generated and increment steps by 1. CloseConstrainedSpan
//   appends exactly one delimiter token while steps grows by 1. In the
//   constrained append branches, AppendConstrainedToken appends one token and
//   the iteration also increments steps by 1, so |generated| never exceeds
//   |generatedPrefix| + steps.
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var steps := 0;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant insideConstrainedOut ==> generated[|generated| - |currentConstrainedOut|..] == currentConstrainedOut
  invariant |generated| <= |generatedPrefix| + steps
  invariant cost == 0
  invariant helpers.cost <= steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    lm.GenerateLogits(prompt + generated);
    var argmax := helpers.GetHighestLogitToken(lm);
    var argmaxLogit := helpers.GetTokenLogit(lm, argmax);
    var openLogit := helpers.GetTokenLogit(lm, "<<");

    if openLogit >= argmaxLogit - 2.0 && argmax != eosToken && argmax != "<<" {
      helpers.cost := helpers.cost + 1;
      steps := steps + 1;
      generated := generated + ["<<"];
      insideConstrainedOut := true;
      currentConstrainedOut := [];
    } else {
      var next := helpers.UnconstrainedStep(lm, prompt, generated);
      steps := steps + 1;
      if next == eosToken {
        break;
      } else {
        generated := generated + [next];
        if next == "<<" {
          insideConstrainedOut := true;
          currentConstrainedOut := [];
        }
      }
    }
  } else {
    if parser.IsCompletePrefix(currentConstrainedOut) {
      var closedGenerated, closedInside, closedCurrent := helpers.CloseConstrainedSpan(
        lm, parser, generated, currentConstrainedOut
      );
      generated := closedGenerated;
      insideConstrainedOut := closedInside;
      currentConstrainedOut := closedCurrent;
      steps := steps + 1;
    } else {
      var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
      lm.GenerateLogits(constrainedPrompt + currentConstrainedOut);
      var argmax := helpers.GetHighestLogitToken(lm);
      var argmaxValid := helpers.IsTokenValidNext(parser, currentConstrainedOut, argmax);

      if argmaxValid && argmax != eosToken {
        var appendedGenerated, appendedInside, appendedCurrent := helpers.AppendConstrainedToken(
          lm, parser, generated, currentConstrainedOut, argmax
        );
        generated := appendedGenerated;
        insideConstrainedOut := appendedInside;
        currentConstrainedOut := appendedCurrent;
        helpers.cost := helpers.cost + 1;
        steps := steps + 1;
      } else {
        var next := helpers.ConstrainedStep(lm, parser, constrainedPrompt, currentConstrainedOut, eosToken);
        steps := steps + 1;
        if next == eosToken {
          break;
        } else {
          var appendedGenerated2, appendedInside2, appendedCurrent2 := helpers.AppendConstrainedToken(
            lm, parser, generated, currentConstrainedOut, next
          );
          generated := appendedGenerated2;
          insideConstrainedOut := appendedInside2;
          currentConstrainedOut := appendedCurrent2;
        }
      }
    }
  }
}

cost := steps;

